from __future__ import annotations

import csv
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

from ..core.paths import to_project_relative


def _auto_stats_paths(project_root: Path) -> List[Path]:
    """Try to locate *.stats files generated by SourcererCC tokenizer."""
    candidates: List[Path] = []
    default_dir = project_root.parent / "SourcererCC" / "tokenizers" / "file-level" / "files_stats"
    if default_dir.is_dir():
        candidates.append(default_dir)
    return candidates


def _normalize_stats_inputs(stats_inputs: Optional[Iterable[Path]], project_root: Path) -> List[Path]:
    paths: List[Path] = []
    if stats_inputs:
        for raw in stats_inputs:
            path = Path(raw)
            if path.is_dir():
                paths.extend(sorted(path.glob("*.stats")))
            elif path.suffix == ".stats" and path.exists():
                paths.append(path)
    else:
        for candidate in _auto_stats_paths(project_root):
            paths.extend(sorted(candidate.glob("*.stats")))
    return paths


def _load_stats_map(stats_files: Iterable[Path]) -> Dict[Tuple[str, int], Tuple[Path, Optional[int]]]:
    mapping: Dict[Tuple[str, int], Tuple[Path, Optional[int]]] = {}
    for stats_file in stats_files:
        with stats_file.open("r", encoding="utf-8", newline="") as fh:
            reader = csv.reader(fh)
            for row in reader:
                if len(row) < 7:
                    continue
                project_id = row[0].strip()
                try:
                    file_id = int(row[1])
                except ValueError:
                    continue
                rel_path = row[3].strip() or row[2].strip()
                if not rel_path:
                    continue
                try:
                    line_count = int(row[6])
                except ValueError:
                    line_count = None
                mapping[(project_id, file_id)] = (Path(rel_path), line_count)
    return mapping


def _iter_pairs(pairs_file: Path) -> Iterable[Tuple[str, Sequence[str]]]:
    """Yield tuples of (kind, parts). kind='path' for full CSV rows, 'id' for file-id pairs."""
    for line in pairs_file.read_text(encoding="utf-8", errors="ignore").splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        for delimiter in ("\t", ","):
            reader = csv.reader([line], delimiter=delimiter)
            row = next(reader)
            if row and (len(row) > 1 or delimiter == ","):
                parts = row
                break
        else:
            parts = line.split()

        if len(parts) >= 6:
            yield "path", parts[:6]
        elif len(parts) == 4:
            yield "id", parts


def convert_sourcerercc(
    pairs_file: Path,
    project_root: Path,
    output_csv: Path,
    stats_paths: Optional[Iterable[Path]] = None,
) -> Path:
    project_root = project_root.resolve()
    stats_files = _normalize_stats_inputs(stats_paths, project_root)
    stats_map = _load_stats_map(stats_files) if stats_files else {}

    rows = []
    for kind, parts in _iter_pairs(pairs_file):
        if kind == "path":
            path1_raw, start1_raw, end1_raw, path2_raw, start2_raw, end2_raw = parts
            try:
                start1 = int(float(start1_raw))
                end1 = int(float(end1_raw))
                start2 = int(float(start2_raw))
                end2 = int(float(end2_raw))
            except ValueError:
                continue
            rows.append(
                {
                    "file1_path": to_project_relative(Path(path1_raw), project_root),
                    "file1_start": start1,
                    "file1_end": end1,
                    "file2_path": to_project_relative(Path(path2_raw), project_root),
                    "file2_start": start2,
                    "file2_end": end2,
                }
            )
            continue

        project1, file_id1_raw, project2, file_id2_raw = parts
        try:
            file_id1 = int(file_id1_raw)
            file_id2 = int(file_id2_raw)
        except ValueError:
            continue

        meta1 = stats_map.get((project1.strip(), file_id1))
        meta2 = stats_map.get((project2.strip(), file_id2))
        if not meta1 or not meta2:
            continue

        rel_path1, line_count1 = meta1
        rel_path2, line_count2 = meta2

        start1 = 0
        end1 = max((line_count1 or 1) - 1, 0)
        start2 = 0
        end2 = max((line_count2 or 1) - 1, 0)

        abs_path1 = (project_root / rel_path1).resolve() if not rel_path1.is_absolute() else rel_path1
        abs_path2 = (project_root / rel_path2).resolve() if not rel_path2.is_absolute() else rel_path2

        rows.append(
            {
                "file1_path": to_project_relative(abs_path1, project_root),
                "file1_start": start1,
                "file1_end": end1,
                "file2_path": to_project_relative(abs_path2, project_root),
                "file2_start": start2,
                "file2_end": end2,
            }
        )

    output_csv.parent.mkdir(parents=True, exist_ok=True)
    with output_csv.open("w", encoding="utf-8", newline="") as fh:
        writer = csv.DictWriter(
            fh,
            fieldnames=[
                "file1_path",
                "file1_start",
                "file1_end",
                "file2_path",
                "file2_start",
                "file2_end",
            ],
        )
        writer.writeheader()
        for row in rows:
            writer.writerow(row)
    return output_csv


__all__ = ["convert_sourcerercc"]
